            <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
              {journey.phases.length > 0 && (
                <Box role="group" aria-label="Timeline navigation" sx={{ display: "flex", gap: "8px" }}>
                  <MsqdxButton
                    variant="outlined"
                    size="small"
                    onClick={() => scrollRelative(-1)}
                    disabled={activePhaseIndex === 0}
                    aria-label="Scroll to previous phase"
                  >
                    <MsqdxIcon name="chevron_left" customSize={18} />
                  </MsqdxButton>
                  <MsqdxButton
                    variant="outlined"
                    size="small"
                    onClick={() => scrollRelative(1)}
                    disabled={journey.phases.length === 0 || activePhaseIndex === journey.phases.length - 1}
                    aria-label="Scroll to next phase"
                  >
                    <MsqdxIcon name="chevron_right" customSize={18} />
                  </MsqdxButton>
                </Box>
              )}
              <MsqdxButton
                variant="outlined"
                size="small"
                onClick={handleAddPhase}
                disabled={addingPhase}
                startIcon={<MsqdxIcon name="add" customSize={16} />}
              >
                {t("journeys.editor.newPhase")}
              </MsqdxButton>
            </Box>
          </Box>

          {journey.phases.length === 0 && !phaseFormExpanded ? (
            <MsqdxTypography variant="body2" sx={{ color: "text.secondary" }}>
              No phases yet. Add your first phase to get started.
            </MsqdxTypography>
          ) : (
            <Box sx={{ display: "flex", flexDirection: "column", gap: 1.5, mb: 2 }}>
              <Box
                role="tablist"
                aria-label="Journey phase steps"
                sx={{
                  display: "flex",
                  gap: 0.5,
                  overflowX: "auto",
                  pb: 0.5,
                  "&::-webkit-scrollbar": { height: 6 },
                  "&::-webkit-scrollbar-thumb": {
                    backgroundColor: "action.disabled",
                    borderRadius: 3,
                    "&:hover": { backgroundColor: "action.active" },
                  },
                }}
              >
                {journey.phases.map((phase, index) => (
                  <MsqdxButton
                    key={phase.id}
                    variant={index === activePhaseIndex ? "contained" : "outlined"}
                    size="small"
                    onClick={() => scrollToPhase(index)}
                    aria-current={index === activePhaseIndex ? "step" : undefined}
                    aria-label={`Phase ${index + 1}: ${phase.name}`}
                    sx={{
                      flexShrink: 0,
                      minWidth: 80,
                      justifyContent: "flex-start",
                      gap: 0.5,
                    }}
                  >
                    <Box component="span" sx={{ fontWeight: 700, fontSize: "0.75rem" }}>{index + 1}</Box>
                    <Box component="span" sx={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{phase.name}</Box>
                  </MsqdxButton>
                ))}
                <MsqdxButton
                  variant="outlined"
                  size="small"
                  onClick={handleAddPhase}
                  disabled={addingPhase}
                  startIcon={<MsqdxIcon name="add" customSize={16} />}
                  sx={{ flexShrink: 0 }}
                >
                  {t("journeys.editor.addPhase")}
                </MsqdxButton>
              </Box>
              <Box
                ref={timelineRef}
                onScroll={handleTimelineScroll}
                tabIndex={0}
                onKeyDown={handleTimelineKeyDown}
                aria-label="Journey phases timeline"
                sx={{
                  flex: 1,
                  overflowX: "auto",
                  overflowY: "hidden",
                  display: "flex",
                  gap: 2,
                  p: 2,
                  pb: 3,
                  "&:focus-visible": { outline: "2px solid", outlineColor: "primary.main", outlineOffset: 2 },
                  "&::-webkit-scrollbar": { height: 8 },
                  "&::-webkit-scrollbar-thumb": {
                    backgroundColor: "action.disabled",
                    borderRadius: 4,
                    "&:hover": { backgroundColor: "action.active" },
                  },
                }}
              >
                {journey.phases.map((phase, index) => (
                  <MsqdxGlassJourneyPhaseCard
                    key={phase.id}
                    phase={phase}
                    index={index}
                    isActive={index === activePhaseIndex}
                    journeyId={journeyId}
                    journey={{
                      name: journey.name,
                      journey_type: journey.journey_type,
                      description: journey.description,
                      target_group_id: journey.target_group_id,
                    }}
                    onSave={handleSavePhase}
                    onDelete={handleDeletePhase}
                  />
                ))}
                {phaseFormExpanded ? (
                  <MsqdxCard variant="flat" borderRadius="button" sx={{ minWidth: 380, p: 2, borderColor: THEME_ACCENT.borderColor }}>
                    <Box component="form" onSubmit={handleSubmitPhase} aria-label="Create new phase" sx={{ display: "flex", flexDirection: "column", gap: 2 }}>
                      <Box sx={{ display: "flex", alignItems: "flex-start", gap: 1.5 }}>
                        <Box sx={{ width: 32, height: 32, borderRadius: "full", bgcolor: "primary.main", color: "primary.contrastText", display: "flex", alignItems: "center", justifyContent: "center", fontSize: "0.875rem", fontWeight: 700 }}>
                          {editingPhaseId ? journey.phases.findIndex((p) => p.id === editingPhaseId) + 1 : journey.phases.length + 1}
                        </Box>
                        <Box sx={{ flex: 1 }}>
                          <MsqdxTypography variant="caption" sx={{ color: "text.secondary" }}>{editingPhaseId ? t("journeys.editor.editPhase") : t("journeys.editor.newPhase")}</MsqdxTypography>
                          <MsqdxTypography variant="h6" weight="semibold">{editingPhaseId ? t("journeys.editor.updateDetails") : t("journeys.editor.defineNext")}</MsqdxTypography>
                        </Box>
                        {editingPhaseId && (
                          <MsqdxButton variant="text" size="small" onClick={() => { setPhaseFormExpanded(false); setEditingPhaseId(null); setPhaseFormData({ name: "", description: "", phase_order: journey.phases.length + 1, expected_duration_min: undefined, expected_duration_max: undefined, duration_unit: "minutes", expected_emotion: undefined, emotion_intensity: undefined }); setMomentDrafts([]); setMomentsError(null); setError(null); }} disabled={addingPhase} aria-label="Cancel editing"><MsqdxIcon name="close" customSize={18} /></MsqdxButton>
                        )}
                      </Box>
                      {error && <MsqdxTypography variant="body2" color="error">Error: {error}</MsqdxTypography>}
                      <MsqdxFormField label="Name *" value={phaseFormData.name} onChange={(e) => setPhaseFormData({ ...phaseFormData, name: e.target.value })} placeholder={t("journeys.editor.placeholderPhaseName")} required disabled={addingPhase} fullWidth size="small" sx={FORM_FIELD_ACCENT_SX} />
                      <MsqdxTextareaField label={t("journeys.editor.phaseDescriptionLabel")} value={phaseFormData.description} onChange={(e) => setPhaseFormData({ ...phaseFormData, description: e.target.value })} placeholder={t("journeys.editor.placeholderDescription")} minRows={3} disabled={addingPhase} fullWidth sx={FORM_FIELD_ACCENT_SX} />
                      <Box sx={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 1.5 }}>
                        <MsqdxFormField label={t("journeys.editor.durationMin")} value={String(phaseFormData.expected_duration_min ?? "")} onChange={(e) => setPhaseFormData({ ...phaseFormData, expected_duration_min: e.target.value ? parseInt(e.target.value) : undefined })} type="number" disabled={addingPhase} size="small" sx={FORM_FIELD_ACCENT_SX} />
                        <MsqdxFormField label={t("journeys.editor.durationMax")} value={String(phaseFormData.expected_duration_max ?? "")} onChange={(e) => setPhaseFormData({ ...phaseFormData, expected_duration_max: e.target.value ? parseInt(e.target.value) : undefined })} type="number" disabled={addingPhase} size="small" sx={FORM_FIELD_ACCENT_SX} />
                        <MsqdxSelect label={t("journeys.editor.unit")} value={phaseFormData.duration_unit} onChange={(e: any) => setPhaseFormData({ ...phaseFormData, duration_unit: e.target.value })} options={[{ value: "minutes", label: t("journeys.editor.minutes") }, { value: "hours", label: t("journeys.editor.hours") }, { value: "days", label: t("journeys.editor.days") }]} disabled={addingPhase} size="small" sx={FORM_FIELD_ACCENT_SX} />
                      </Box>
                      <MsqdxFormField label={t("journeys.editor.expectedEmotion")} value={phaseFormData.expected_emotion ?? ""} onChange={(e) => setPhaseFormData({ ...phaseFormData, expected_emotion: e.target.value || undefined })} placeholder={t("journeys.editor.placeholderEmotion")} disabled={addingPhase} size="small" fullWidth sx={FORM_FIELD_ACCENT_SX} />
                      <Box>
                        <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center", mb: 1 }}>
                          <Box>
                            <MsqdxTypography variant="caption" weight="semibold">{t("journeys.editor.journeyMoments")}</MsqdxTypography>
                            <MsqdxTypography variant="caption" sx={{ color: "text.secondary", display: "block" }}>{t("journeys.editor.journeyMomentsHint")}</MsqdxTypography>
                          </Box>
                          <Box sx={{ display: "flex", gap: 0.5 }}>
                            <MsqdxGlassAiButton templates={[{ id: "journey.moments", label: t("journeys.editor.aiSuggestion"), maxSuggestions: 4 }]} onClick={triggerMomentGeneration} disabled={!journey || addingPhase || aiAssistLoading} loading={aiAssistLoading} size="small" title={t("journeys.editor.aiSuggestion")} />
                            <MsqdxButton variant="outlined" size="small" onClick={addMomentDraft} disabled={addingPhase} startIcon={<MsqdxIcon name="add_circle" customSize={14} />}>{t("journeys.editor.addMoment")}</MsqdxButton>
                          </Box>
                        </Box>
                        {momentsError && <MsqdxTypography variant="caption" color="error" sx={{ display: "block", mb: 1 }}>{momentsError}</MsqdxTypography>}
                        {momentDrafts.length === 0 ? (
                          <MsqdxTypography variant="body2" sx={{ color: "text.secondary", py: 2 }}>{t("journeys.editor.noMoments")}</MsqdxTypography>
                        ) : (
                          <Box sx={{ display: "flex", flexDirection: "column", gap: 1.5 }}>
                            {momentDrafts.map((moment) => (
                              <Box key={moment.id} sx={{ display: "flex", gap: 1.5, alignItems: "flex-start", p: 1.5, border: "1px solid", borderColor: "divider", borderRadius: 1 }}>
                                <Box sx={{ width: 140, flexShrink: 0 }}>
                                  <MsqdxSelect label={t("journeys.editor.momentType")} value={moment.element_type} onChange={(e: any) => updateMomentDraft(moment.id, { element_type: e.target.value })} options={ELEMENT_TYPE_OPTIONS.map((opt) => ({ value: opt, label: opt.replace("_", " ") }))} disabled={addingPhase} size="small" sx={FORM_FIELD_ACCENT_SX} />
                                </Box>
                                <Box sx={{ flex: 1 }}>
                                  <MsqdxTextareaField label={t("journeys.editor.momentDescription")} value={moment.content} onChange={(e) => updateMomentDraft(moment.id, { content: e.target.value })} placeholder={t("journeys.editor.momentDescriptionPlaceholder")} minRows={2} disabled={addingPhase} fullWidth sx={FORM_FIELD_ACCENT_SX} />
                                </Box>
                                <MsqdxButton variant="text" size="small" onClick={() => removeMomentDraft(moment.id)} disabled={addingPhase} aria-label={t("journeys.editor.removeMoment")} sx={{ alignSelf: "flex-start", mt: 2 }}><MsqdxIcon name="close" customSize={14} /></MsqdxButton>
                              </Box>
                            ))}
                          </Box>
                        )}
                      </Box>
                      <Box sx={{ display: "flex", gap: 1, justifyContent: "flex-end", pt: 1 }}>
                        <MsqdxButton variant="text" size="small" onClick={() => { setPhaseFormExpanded(false); setEditingPhaseId(null); setMomentDrafts([]); setMomentsError(null); setError(null); setPhaseFormData({ name: "", description: "", phase_order: journey.phases.length + 1, expected_duration_min: undefined, expected_duration_max: undefined, duration_unit: "minutes", expected_emotion: undefined, emotion_intensity: undefined }); }} disabled={addingPhase}>{t("journeys.editor.cancel")}</MsqdxButton>
                        <MsqdxButton type="submit" variant="contained" size="small" sx={{ backgroundColor: THEME_ACCENT.backgroundColor, "&:hover": { backgroundColor: THEME_ACCENT.backgroundColor, filter: "brightness(1.1)" } }} disabled={addingPhase || !phaseFormData.name.trim()} startIcon={<MsqdxIcon name={addingPhase ? "hourglass_empty" : editingPhaseId ? "save" : "add"} customSize={14} />}>{addingPhase ? (editingPhaseId ? t("journeys.editor.updating") : t("journeys.editor.adding")) : (editingPhaseId ? t("journeys.editor.phaseUpdated") : t("journeys.editor.addPhase"))}</MsqdxButton>
                      </Box>
                    </Box>
                  </MsqdxCard>
                ) : (
                  <MsqdxCard
                    variant="flat"
                    sx={{
                      minWidth: 380,
                      p: 3,
                      position: "relative",
                      borderStyle: "dashed",
                      opacity: addingPhase || aiAssistLoading ? 0.6 : 1,
                      cursor: addingPhase || aiAssistLoading ? "not-allowed" : "pointer",
                    }}
                  >
                    <Box
                      component="button"
                      type="button"
                      onClick={handleAddPhase}
                      disabled={addingPhase || aiAssistLoading}
                      aria-label="Add a new phase"
                      sx={{
                        width: "100%",
                        background: "none",
                        border: "none",
                        padding: 0,
                        cursor: addingPhase || aiAssistLoading ? "not-allowed" : "pointer",
                        textAlign: "left",
                      }}
                    >
                      <Box sx={{ display: "flex", alignItems: "center", justifyContent: "center", width: 56, height: 56, borderRadius: "full", bgcolor: "action.hover", mb: 1.5 }}>
                        <MsqdxIcon name="add" customSize={28} />
                      </Box>
                      <MsqdxTypography variant="h6" weight="semibold" sx={{ mb: 0.5 }}>{t("journeys.editor.addPhase")}</MsqdxTypography>
                      <MsqdxTypography variant="body2" sx={{ color: "text.secondary" }}>
                        {t("journeys.editor.addPhaseCardHint")}
                      </MsqdxTypography>
                    </Box>
                    <Box sx={{ position: "absolute", bottom: 16, right: 16 }} onClick={(e) => e.stopPropagation()}>
                      <MsqdxGlassAiButton
                        templates={[{ id: "journey.phase.create", label: "AI Generate Phase", maxSuggestions: 1 }]}
                        onClick={handleGeneratePhaseWithAI}
                        disabled={!journey || addingPhase || aiAssistLoading}
                        loading={aiAssistLoading}
                        size="small"
                        title="Generate phase with AI"
                      />
                    </Box>
                  </MsqdxCard>
                )}
              </Box>
              <MsqdxTypography variant="caption" sx={{ color: "text.secondary", display: "block", mt: 1 }} component="div" aria-live="polite">
                {t("journeys.editor.phaseOf", { current: activePhaseIndex + 1, total: journey.phases.length })}
              </MsqdxTypography>
            </Box>
          )}
        </div>
      </div>
    </div>
  );
}

