                      <div style={{ minHeight: "600px" }}>
                        <PromptBuilder
                          initialPrompt={editingTemplate.prompt}
                          onPromptChange={(newPrompt) => {
                            setEditingTemplate({ ...editingTemplate, prompt: newPrompt });
