"use client";

import { useState, useRef, useEffect, useCallback } from "react";
import { Box, useTheme, alpha } from "@mui/material";
import { MsqdxIcon, MsqdxButton, MsqdxTypography, MsqdxInput } from "@msqdx/react";
import { MsqdxGlassEditButton, MsqdxGlassAiButtonIcon } from "./";
import { useInlineEdit } from "../hooks/use-inline-edit";
import { MsqdxGlassInlineEditControls } from "../msqdx-glass-inline-edit-controls";
import { MsqdxGlassChip } from "./msqdx-glass-chip";
import { INPUT_ACCENT_SX } from "../../lib/theme-accent";

export type MsqdxGlassChipEditorProps = {
  /**
   * Section label (e.g., "Interessen")
   */
  label: string;
  /**
   * Array of chip values
   */
  chips: string[];
  /**
   * CSS class name for chips (e.g., "--dashboard --interest")
   */
  chipClassName?: string;
  /**
   * Callback when chips are saved
   */
  onSave: (chips: string[]) => Promise<void>;
  /**
   * Whether editing is enabled
   */
  editable?: boolean;
  /**
   * Message to show when no chips exist
   */
  emptyMessage?: string;
  /**
   * Optional callback for AI suggestions
   */
  onAiSuggest?: () => Promise<void>;
  /**
   * Whether AI suggestion is loading
   */
  aiLoading?: boolean;
  /**
   * Optional highlighted chips (case-insensitive match)
   */
  highlightedChips?: string[];
};

export const MsqdxGlassChipEditor = ({
  label,
  chips,
  chipClassName = "",
  onSave,
  editable = true,
  emptyMessage = "Keine Einträge",
  onAiSuggest,
  aiLoading = false,
  highlightedChips = []
}: MsqdxGlassChipEditorProps) => {
  const theme = useTheme();
  const containerRef = useRef<HTMLDivElement>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [editingIndex, setEditingIndex] = useState<number | null>(null);
  const [editingValue, setEditingValue] = useState("");
  const [newChipValue, setNewChipValue] = useState("");
  const [savePending, setSavePending] = useState(false);
  const editInputWrapperRef = useRef<HTMLDivElement>(null);
  const newInputWrapperRef = useRef<HTMLDivElement>(null);

  // Array comparison function (order-independent for hasChanges)
  const arrayIsEqual = useCallback((a: string[], b: string[]): boolean => {
    if (a.length !== b.length) return false;
    const aSorted = [...a].map(s => s.trim().toLowerCase()).sort();
    const bSorted = [...b].map(s => s.trim().toLowerCase()).sort();
    return JSON.stringify(aSorted) === JSON.stringify(bSorted);
  }, []);

  const chipEdit = useInlineEdit({
    initialValue: chips,
    currentValue: chips,
    isEqual: arrayIsEqual
  });
  const syncChips = chipEdit.sync;

  // Ensure external updates sync when not editing
  useEffect(() => {
    if (!isEditing) {
      syncChips();
    }
  }, [chips, isEditing, syncChips]);

  // Focus input when entering edit mode
  useEffect(() => {
    if (isEditing && editingIndex === null) {
      const input = newInputWrapperRef.current?.querySelector("input");
      input?.focus();
    }
  }, [isEditing, editingIndex]);

  // Focus edit input when editing a chip
  useEffect(() => {
    if (editingIndex !== null) {
      const input = editInputWrapperRef.current?.querySelector("input");
      input?.focus();
      input?.select();
    }
  }, [editingIndex]);

  const handleStartEdit = () => {
    setIsEditing(true);
    chipEdit.sync(); // Ensure we start with current values
  };

  const handleCancelEdit = () => {
    setIsEditing(false);
    setEditingIndex(null);
    setEditingValue("");
    setNewChipValue("");
    chipEdit.reset();
  };

  const handleSave = async () => {
    setSavePending(true);
    try {
      await onSave(chipEdit.value);
      chipEdit.sync();
      setIsEditing(false);
      setEditingIndex(null);
      setEditingValue("");
      setNewChipValue("");
    } catch (error) {
      console.error("Failed to save chips:", error);
    } finally {
      setSavePending(false);
    }
  };

  const handleAddChip = useCallback((value: string) => {
    const trimmed = value.trim();
    if (!trimmed) return;

    // Check for duplicates (case-insensitive)
    const normalized = trimmed.toLowerCase();
    const exists = chipEdit.value.some(chip => chip.trim().toLowerCase() === normalized);
    if (exists) return;

    chipEdit.setValue([...chipEdit.value, trimmed]);
    setNewChipValue("");
  }, [chipEdit]);

  const handleRemoveChip = useCallback((index: number) => {
    chipEdit.setValue(chipEdit.value.filter((_, i) => i !== index));
    if (editingIndex === index) {
      setEditingIndex(null);
      setEditingValue("");
    }
  }, [chipEdit, editingIndex]);

  const handleStartEditChip = useCallback((index: number, currentValue: string) => {
    setEditingIndex(index);
    setEditingValue(currentValue);
  }, []);

  const handleSaveEditChip = useCallback(() => {
    if (editingIndex === null) return;

    const trimmed = editingValue.trim();
    if (!trimmed) {
      // Empty value = remove chip
      handleRemoveChip(editingIndex);
      return;
    }

    // Check for duplicates (case-insensitive), but allow if editing same chip
    const normalized = trimmed.toLowerCase();
    const exists = chipEdit.value.some((chip, i) => 
      i !== editingIndex && chip.trim().toLowerCase() === normalized
    );

    if (exists) {
      // Duplicate found, cancel edit
      setEditingIndex(null);
      setEditingValue("");
      return;
    }

    const updated = [...chipEdit.value];
    updated[editingIndex] = trimmed;
    chipEdit.setValue(updated);
    setEditingIndex(null);
    setEditingValue("");
  }, [editingIndex, editingValue, chipEdit, handleRemoveChip]);

  const handleCancelEditChip = useCallback(() => {
    setEditingIndex(null);
    setEditingValue("");
  }, []);

  const handleKeyDown = useCallback((e: React.KeyboardEvent, isEdit: boolean, index: number | null) => {
    if (e.key === "Enter") {
      e.preventDefault();
      if (isEdit && index !== null) {
        handleSaveEditChip();
      } else {
        handleAddChip(newChipValue);
      }
    } else if (e.key === "Escape") {
      if (isEdit && index !== null) {
        handleCancelEditChip();
      } else {
        handleCancelEdit();
      }
    }
  }, [newChipValue, handleAddChip, handleSaveEditChip, handleCancelEditChip, handleCancelEdit]);

  const displayChips = chipEdit.value;
  const hasChips = displayChips.length > 0;
  const showEmptyState = !isEditing && !hasChips;

  return (
    <div className="msqdx-glass-dashboard-card-section" ref={containerRef}>
      <Box
        sx={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          mb: 1
        }}
      >
        {label && (
          <MsqdxTypography
            variant="caption"
            sx={{
              fontWeight: 600,
              textTransform: "uppercase",
              letterSpacing: "0.05em",
              color: "text.secondary",
            }}
          >
            {label}
          </MsqdxTypography>
        )}
        {editable && !isEditing && (
          <Box sx={{ display: "flex", gap: 0.5, alignItems: "center" }}>
            {onAiSuggest && (
              <MsqdxGlassAiButtonIcon
                onClick={onAiSuggest}
                disabled={aiLoading}
                loading={aiLoading}
                size="small"
                fontSize={18}
                title="AI Vorschlag"
                aria-label="AI Vorschlag"
              />
            )}
            {hasChips && (
              <MsqdxGlassEditButton
                onClick={handleStartEdit}
                size="small"
                fontSize={18}
                aria-label="Edit chips"
              />
            )}
          </Box>
        )}
      </Box>

      {showEmptyState ? (
        <Box sx={{ color: "text.secondary", fontStyle: "italic", fontSize: "0.875rem" }}>
          {emptyMessage}
        </Box>
      ) : (
        <>
          <Box
            sx={{
              display: "flex",
              flexWrap: "wrap",
              gap: 0.5,
              mb: isEditing ? 1 : 0
            }}
          >
            {displayChips.map((chip, idx) => (
              <Box
                key={idx}
                sx={{
                  display: "inline-flex",
                  alignItems: "center",
                  gap: 0.5
                }}
              >
                {isEditing && editingIndex === idx ? (
                  <Box ref={editInputWrapperRef} sx={{ minWidth: "120px" }}>
                    <MsqdxInput
                      value={editingValue}
                      onChange={(e) => setEditingValue(e.target.value)}
                      onKeyDown={(e) => handleKeyDown(e, true, idx)}
                      onBlur={handleSaveEditChip}
                      size="small"
                      sx={INPUT_ACCENT_SX}
                    />
                  </Box>
                ) : (
                  <MsqdxGlassChip
                    variant={chipClassName.includes("--trait") ? "trait" : 
                            chipClassName.includes("--vocab") ? "vocab" :
                            chipClassName.includes("--pain") ? "pain" :
                            chipClassName.includes("--goal") ? "goal" :
                            chipClassName.includes("--value") ? "value" :
                            chipClassName.includes("--interest") ? "interest" :
                            chipClassName.includes("--social") ? "social" : "trait"}
                    dashboard={true}
                    highlighted={highlightedChips.some((highlight) => highlight.trim().toLowerCase() === chip.trim().toLowerCase())}
                    onClick={isEditing ? () => handleStartEditChip(idx, chip) : undefined}
                  >
                    {chip}
                  </MsqdxGlassChip>
                )}
                {isEditing && editingIndex !== idx && (
                  <MsqdxButton
                    variant="text"
                    size="small"
                    onClick={() => handleRemoveChip(idx)}
                    aria-label="Remove"
                    sx={{
                      minWidth: 24,
                      minHeight: 24,
                      p: "2px",
                      "&:hover": {
                        backgroundColor: alpha(theme.palette.error.main, 0.1),
                      },
                    }}
                  >
                    <MsqdxIcon name="close" customSize={16} />
                  </MsqdxButton>
                )}
              </Box>
            ))}
            {isEditing && (
              <Box ref={newInputWrapperRef} sx={{ minWidth: "180px" }}>
                <MsqdxInput
                  value={newChipValue}
                  onChange={(e) => setNewChipValue(e.target.value)}
                  onKeyDown={(e) => handleKeyDown(e, false, null)}
                  placeholder="Neuen Eintrag hinzufügen..."
                  size="small"
                  sx={INPUT_ACCENT_SX}
                />
              </Box>
            )}
          </Box>

          {isEditing && chipEdit.hasChanges && (
            <MsqdxGlassInlineEditControls
              hasChanges={chipEdit.hasChanges}
              saving={savePending}
              onSave={handleSave}
              onDiscard={handleCancelEdit}
              anchorElement={containerRef.current}
              position="top"
            />
          )}
        </>
      )}

      {editable && showEmptyState && (
        <Box sx={{ display: "flex", gap: 1, alignItems: "center", mt: 1 }}>
          {onAiSuggest && (
            <Box sx={{ display: "flex", alignItems: "center", gap: 0.5 }}>
              <MsqdxGlassAiButtonIcon
              onClick={onAiSuggest}
              disabled={aiLoading}
                loading={aiLoading}
                size="small"
                fontSize={18}
              title="AI Vorschlag"
                aria-label="AI Vorschlag"
              />
              <Box component="span" sx={{ fontSize: "0.875rem" }}>
                AI Vorschlag
              </Box>
            </Box>
          )}
          <MsqdxButton
            variant="text"
            size="small"
            onClick={handleStartEdit}
            startIcon={<MsqdxIcon name="add" customSize={18} />}
            aria-label="Add"
          >
            Add
          </MsqdxButton>
        </Box>
      )}
    </div>
  );
};

"use client";

import { useMemo } from "react";
import clsx from "clsx";

export type MsqdxGlassChipVariant = 
  | "trait" 
  | "vocab" 
  | "pain" 
  | "goal" 
  | "value" 
  | "interest" 
  | "social"
  | "draft"
  | "published"
  | "archived"
  | "success"
  | "processing"
  | "error"
  | "pending";

export type MsqdxGlassChipSize = "small" | "medium" | "large";

export type MsqdxGlassChipProps = {
  /**
   * Chip content/text
   */
  children: React.ReactNode;
  /**
   * Chip variant (determines color scheme)
   */
  variant?: MsqdxGlassChipVariant;
  /**
   * Size variant
   */
  size?: MsqdxGlassChipSize;
  /**
   * Whether this chip is highlighted (e.g., newly added)
   */
  highlighted?: boolean;
  /**
   * Additional CSS classes
   */
  className?: string;
  /**
   * Click handler
   */
  onClick?: () => void;
  /**
   * Additional inline styles
   */
  style?: React.CSSProperties;
  /**
   * Whether chip is in dashboard context
   */
  dashboard?: boolean;
  /**
   * Priority level (for pain/goal/trait variants)
   */
  priority?: "high" | "medium" | "low";
};

/**
 * Centralized Chip Component
 * 
 * Provides consistent styling and behavior for all chip types across the application.
 * Supports different variants (trait, vocab, pain, goal, etc.) with configurable
 * colors, sizes, and states.
 */
export const MsqdxGlassChip = ({
  children,
  variant = "trait",
  size = "small",
  highlighted = false,
  className = "",
  onClick,
  style,
  dashboard = false,
  priority
}: MsqdxGlassChipProps) => {
  const chipClasses = useMemo(() => {
    const classes = ["msqdx-glass-chip"];

    if (dashboard) {
      classes.push("--dashboard");
    }

    if (variant) {
      classes.push(`--${variant}`);
    }

    if (highlighted) {
      classes.push("--is-new");
    }

    if (priority && (variant === "pain" || variant === "goal" || variant === "trait")) {
      classes.push(`--${variant}-${priority}`);
    }

    if (className) {
      classes.push(className);
    }

    return clsx(classes);
  }, [variant, size, highlighted, className, dashboard, priority]);

  const defaultStyle: React.CSSProperties = {
    cursor: onClick ? "pointer" : "default",
    display: "inline-flex",
    alignItems: "center",
    ...style
  };

  return (
    <span
      className={chipClasses}
      onClick={onClick}
      style={defaultStyle}
    >
      {children}
    </span>
  );
};

"use client";

import { useCallback, useState, useEffect } from "react";
import { Box, Typography, Stack, Divider } from "@mui/material";
import type { FieldDefinition, getFieldDefinitions, groupFields } from "@msqdx-glass/types";
import { getFieldDefinitions as getFieldDefs, groupFields as groupFieldsHelper } from "@msqdx-glass/types";
import { MsqdxGlassFieldEditor } from "./msqdx-glass-field-editor";

export type MsqdxGlassEntityEditorProps<T extends Record<string, any>> = {
  entityType: "persona" | "targetGroup" | "document" | "knowledge";
  entity: T;
  onSave: (updates: Partial<T>) => Promise<void>;
  fieldOverrides?: Partial<Record<string, FieldDefinition>>; // Für Entity-spezifische Overrides
  inline?: boolean;
  disabled?: boolean;
  showGroups?: boolean; // Zeige Gruppierung an
};

/**
 * Generische Entität-Editor Komponente.
 * Lädt Feld-Definitionen für eine Entität und rendert Edit-Komponenten für alle Felder.
 */
export const MsqdxGlassEntityEditor = <T extends Record<string, any>>({
  entityType,
  entity,
  onSave,
  fieldOverrides = {},
  inline = true,
  disabled = false,
  showGroups = true,
}: MsqdxGlassEntityEditorProps<T>) => {
  const [localEntity, setLocalEntity] = useState<T>(entity);
  const [pendingUpdates, setPendingUpdates] = useState<Partial<T>>({});
  const [saving, setSaving] = useState(false);

  // Load field definitions
  const fieldDefinitions = getFieldDefs(entityType);

  // Apply overrides and filter out undefined fields
  const fields = fieldDefinitions
    .map((field) => {
      const override = fieldOverrides[field.key];
      if (override === undefined && fieldOverrides.hasOwnProperty(field.key)) {
        // Field is explicitly set to undefined in overrides, exclude it
        return null;
      }
      return {
        ...field,
        ...(override || {}),
      };
    })
    .filter((field): field is FieldDefinition => field !== null);

  // Group fields
  const groupedFields = showGroups ? groupFieldsHelper(fields) : { all: fields };

  // Sync local entity when external entity changes
  useEffect(() => {
    setLocalEntity(entity);
    setPendingUpdates({});
  }, [entity]);

  const handleFieldChange = useCallback(
    (key: string, value: any) => {
      setLocalEntity((prev) => ({ ...prev, [key]: value }));
      setPendingUpdates((prev) => ({ ...prev, [key]: value }));
    },
    []
  );

  const handleFieldSave = useCallback(
    async (key: string, value: any) => {
      try {
        await onSave({ [key]: value } as Partial<T>);
        setPendingUpdates((prev) => {
          const next = { ...prev };
          delete next[key as keyof T];
          return next;
        });
        // Update local entity after successful save
        setLocalEntity((prev) => ({ ...prev, [key]: value }));
      } catch (error) {
        console.error(`Save failed for field ${key}:`, error);
        throw error;
      }
    },
    [onSave]
  );

  const handleBulkSave = useCallback(async () => {
    if (Object.keys(pendingUpdates).length === 0) {
      return;
    }

    setSaving(true);
    try {
      await onSave(pendingUpdates);
      setPendingUpdates({});
    } catch (error) {
      console.error("Bulk save failed:", error);
    } finally {
      setSaving(false);
    }
  }, [pendingUpdates, onSave]);

  // Render grouped fields
  const renderGroupedFields = () => {
    return Object.entries(groupedFields).map(([groupName, groupFields]) => (
      <Box key={groupName} sx={{ mb: 3 }}>
        {showGroups && groupName !== "all" && (
          <>
            <Typography
              variant="h6"
              sx={{
                fontSize: "0.875rem",
                fontWeight: 600,
                textTransform: "uppercase",
                letterSpacing: "0.05em",
                mb: 2,
                color: "text.secondary",
              }}
            >
              {groupName}
            </Typography>
            <Divider sx={{ mb: 2 }} />
          </>
        )}
        <Stack spacing={2}>
          {groupFields.map((field) => (
            <Box key={field.key}>
              {inline ? (
                <Box sx={{ display: "flex", alignItems: "flex-start", gap: 2 }}>
                  <Typography
                    variant="body2"
                    sx={{
                      minWidth: "150px",
                      fontWeight: 500,
                      pt: 1,
                    }}
                  >
                    {field.label}
                  </Typography>
                  <Box sx={{ flex: 1 }}>
                    <MsqdxGlassFieldEditor
                      field={field}
                      value={localEntity[field.key]}
                      onChange={handleFieldChange}
                      onSave={handleFieldSave}
                      inline={inline}
                      disabled={disabled}
                    />
                  </Box>
                </Box>
              ) : (
                <MsqdxGlassFieldEditor
                  field={field}
                  value={localEntity[field.key]}
                  onChange={handleFieldChange}
                  onSave={handleFieldSave}
                  inline={false}
                  disabled={disabled}
                />
              )}
            </Box>
          ))}
        </Stack>
      </Box>
    ));
  };

  return (
    <Box className="msqdx-glass-entity-editor">
      {renderGroupedFields()}

      {/* Bulk Save Button (if multiple changes pending) */}
      {Object.keys(pendingUpdates).length > 1 && (
        <Box sx={{ mt: 3, pt: 2, borderTop: "1px solid", borderColor: "divider" }}>
          <button
            className="msqdx-glass-button"
            onClick={handleBulkSave}
            disabled={saving}
            style={{ padding: "0.375rem 0.75rem", fontSize: "0.8125rem" }}
          >
            Save All Changes ({Object.keys(pendingUpdates).length})
          </button>
        </Box>
      )}
    </Box>
  );
};

"use client";

import { useState, useCallback, useRef, useEffect } from "react";
import type { FieldDefinition } from "@msqdx-glass/types";
import { Typography, Box, Checkbox } from "@mui/material";
import { MsqdxIcon, MsqdxSelect, MsqdxFormField, MsqdxTextareaField, MsqdxSlider } from "@msqdx/react";
import { MsqdxGlassEditButton } from "./msqdx-glass-edit-button";
import { useInlineEdit } from "../hooks/use-inline-edit";
import { MsqdxGlassInlineEditControls } from "../msqdx-glass-inline-edit-controls";
import { FORM_FIELD_ACCENT_SX, THEME_ACCENT } from "../../lib/theme-accent";

export type MsqdxGlassFieldEditorProps = {
  field: FieldDefinition;
  value: any;
  onChange: (key: string, value: any) => void;
  onSave?: (key: string, value: any) => Promise<void>;
  inline?: boolean;
  disabled?: boolean;
  onEditStart?: () => void;
  onEditEnd?: () => void;
  forceEditMode?: boolean;
};

/**
 * Generische Feld-Editor Komponente.
 * Unterstützt alle Feld-Typen (text, number, select, textarea, slider, date, boolean).
 */
export const MsqdxGlassFieldEditor = ({
  field,
  value,
  onChange,
  onSave,
  inline = true,
  disabled = false,
  onEditStart,
  onEditEnd,
  forceEditMode = false,
}: MsqdxGlassFieldEditorProps) => {
  const [editing, setEditing] = useState(forceEditMode);

  // Update editing state when forceEditMode changes
  useEffect(() => {
    if (forceEditMode) {
      setEditing(true);
      onEditStart?.();
    }
  }, [forceEditMode, onEditStart]);
  const fieldRef = useRef<HTMLDivElement>(null);

  const inlineEdit = useInlineEdit({
    initialValue: value ?? (field.type === "boolean" ? false : null),
    currentValue: value ?? (field.type === "boolean" ? false : null),
    isEqual: (a, b) => {
      // Handle null/undefined equality
      if (a === null || a === undefined) {
        return b === null || b === undefined;
      }
      if (b === null || b === undefined) {
        return false;
      }
      return a === b;
    },
  });

  const handleSave = useCallback(async () => {
    if (onSave) {
      try {
        await onSave(field.key, inlineEdit.getValue());
        onChange(field.key, inlineEdit.getValue());
        setEditing(false);
        onEditEnd?.();
      } catch (error) {
        console.error(`Save failed for field ${field.key}:`, error);
        throw error;
      }
    } else {
      onChange(field.key, inlineEdit.getValue());
      setEditing(false);
      onEditEnd?.();
    }
  }, [field.key, inlineEdit, onChange, onSave, onEditEnd]);

  const handleCancel = useCallback(() => {
    inlineEdit.reset();
    setEditing(false);
    onEditEnd?.();
  }, [inlineEdit, onEditEnd]);

  // Render field input based on type
  const renderFieldInput = () => {
    const currentValue = inlineEdit.value ?? (field.type === "boolean" ? false : null);

    switch (field.type) {
      case "text":
        return (
          <MsqdxFormField
            label={inline ? "" : field.label}
            value={currentValue ?? ""}
            onChange={(e) => inlineEdit.setValue(e.target.value || null)}
            inputRef={inlineEdit.elementRef as React.RefObject<HTMLInputElement>}
            placeholder={field.config?.placeholder}
            disabled={disabled}
            required={field.config?.required}
            autoFocus
            fullWidth
            sx={FORM_FIELD_ACCENT_SX}
          />
        );

      case "textarea":
        return (
          <MsqdxTextareaField
            label={inline ? "" : field.label}
            value={currentValue ?? ""}
            onChange={(e) => inlineEdit.setValue(e.target.value || null)}
            inputRef={inlineEdit.elementRef as React.RefObject<HTMLInputElement>}
            placeholder={field.config?.placeholder}
            disabled={disabled}
            required={field.config?.required}
            autoFocus
            fullWidth
            minRows={3}
            size="small"
            sx={FORM_FIELD_ACCENT_SX}
          />
        );

      case "number":
        return (
          <MsqdxFormField
            label={inline ? "" : field.label}
            type="number"
            value={currentValue ?? ""}
            onChange={(e) => {
              const numValue = e.target.value ? Number(e.target.value) : null;
              inlineEdit.setValue(numValue);
            }}
            inputRef={inlineEdit.elementRef as React.RefObject<HTMLInputElement>}
            placeholder={field.config?.placeholder}
            disabled={disabled}
            required={field.config?.required}
            autoFocus
            fullWidth
            sx={FORM_FIELD_ACCENT_SX}
          />
        );

      case "slider": {
        const sliderValue = typeof currentValue === "number" ? currentValue : (field.config?.min ?? 0);
        return (
          <Box>
            {/* @ts-expect-error MsqdxSlider ForwardRef type conflicts with React 19 inference */}
            <MsqdxSlider
              value={sliderValue}
              onChange={(_, newValue) => inlineEdit.setValue(Array.isArray(newValue) ? newValue[0] : newValue)}
              min={field.config?.min ?? 0}
              max={field.config?.max ?? 100}
              step={field.config?.step ?? 1}
              disabled={disabled}
              size="small"
              sx={{ color: THEME_ACCENT.color }}
              valueLabelDisplay="on"
            />
          </Box>
        );
      }

      case "select": {
        const options = field.config?.options ?? [];
        const selectOptions = [
          { value: "" as const, label: "—" },
          ...options.map((opt) => ({ value: opt.value, label: opt.label })),
        ];
        return (
          <MsqdxSelect
            label={inline ? "" : field.label}
            options={selectOptions}
            value={currentValue ?? ""}
            onChange={(e) => inlineEdit.setValue(e.target.value || null)}
            inputRef={inlineEdit.elementRef as React.RefObject<HTMLInputElement>}
            disabled={disabled}
            required={field.config?.required}
            autoFocus
            fullWidth
            size="small"
            displayEmpty
          />
        );
      }

      case "boolean":
        return (
          <Checkbox
            inputRef={inlineEdit.elementRef as React.RefObject<HTMLInputElement>}
            checked={currentValue ?? false}
            onChange={(e) => inlineEdit.setValue(e.target.checked)}
            disabled={disabled}
            autoFocus
          />
        );

      case "date":
        return (
          <MsqdxFormField
            label={inline ? "" : field.label}
            type="date"
            value={currentValue ? new Date(currentValue).toISOString().split("T")[0] : ""}
            onChange={(e) => {
              const dateValue = e.target.value ? new Date(e.target.value).toISOString() : null;
              inlineEdit.setValue(dateValue);
            }}
            inputRef={inlineEdit.elementRef as React.RefObject<HTMLInputElement>}
            disabled={disabled}
            required={field.config?.required}
            autoFocus
            fullWidth
            sx={FORM_FIELD_ACCENT_SX}
            InputLabelProps={{ shrink: true }}
          />
        );

      default:
        return <div>Unsupported field type: {field.type}</div>;
    }
  };

  // Start editing when inlineEdit value changes and we're in edit mode
  useEffect(() => {
    if (editing && !inlineEdit.hasChanges) {
      // Reset editing state if changes are discarded
    }
  }, [editing, inlineEdit.hasChanges]);

  // Inline-Edit Mode
  if (inline) {
    if (editing) {
      return (
        <Box ref={fieldRef} sx={{ position: "relative" }}>
          <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
            <Box sx={{ flex: 1 }}>{renderFieldInput()}</Box>
          </Box>
          {inlineEdit.hasChanges && (
            <MsqdxGlassInlineEditControls
              hasChanges={inlineEdit.hasChanges}
              onSave={handleSave}
              onDiscard={handleCancel}
              anchorElement={fieldRef.current}
              position="bottom"
            />
          )}
        </Box>
      );
    } else {
      // Display mode
      let displayValue: React.ReactNode = value ?? null;

      // Format display value based on type
      if (field.type === "select" && value) {
        const option = field.config?.options?.find(opt => opt.value === value);
        displayValue = option ? option.label : value;
      } else if (field.type === "boolean") {
        displayValue = value ? "Yes" : "No";
      } else if (field.type === "slider" && typeof value === "number") {
        displayValue = value;
      } else if (field.type === "date" && value) {
        displayValue = new Date(value).toLocaleDateString();
      }

      return (
        <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
          <Box sx={{ flex: 1 }}>
            {displayValue !== null && displayValue !== undefined && displayValue !== "" ? (
              <Typography variant="body2">{String(displayValue)}</Typography>
            ) : (
              <Typography variant="body2" color="text.secondary" sx={{ fontStyle: "italic" }}>
                —
              </Typography>
            )}
          </Box>
          {!disabled && (
            <MsqdxGlassEditButton
              onClick={() => {
                inlineEdit.sync();
                setEditing(true);
                onEditStart?.();
              }}
              aria-label={`Edit ${field.label}`}
              size="small"
              fontSize={16}
            />
          )}
        </Box>
      );
    }
  }

  // Form Mode (for create flows)
  return (
    <Box>
      <Typography variant="caption" sx={{ mb: 0.5, display: "block" }}>
        {field.label}
        {field.config?.required && (
          <Typography component="span" color="error.main" sx={{ ml: 0.5 }}>
            *
          </Typography>
        )}
      </Typography>
      {renderFieldInput()}
    </Box>
  );
};

"use client";

import { useState, useEffect, useRef, useCallback } from "react";

export type UseInlineEditOptions<T> = {
  /**
   * Initial value
   */
  initialValue: T;
  /**
   * Current value from props (for syncing with external state)
   */
  currentValue?: T;
  /**
   * Comparison function to determine if values are equal
   */
  isEqual?: (a: T, b: T) => boolean;
  /**
   * Callback when value changes
   */
  onChange?: (value: T) => void;
};

export type UseInlineEditReturn<T> = {
  /**
   * Current local value
   */
  value: T;
  /**
   * Set the local value
   */
  setValue: (value: T) => void;
  /**
   * Whether there are unsaved changes
   */
  hasChanges: boolean;
  /**
   * Reset to initial value (discard changes)
   */
  reset: () => void;
  /**
   * Reset to current value (sync with external state)
   */
  sync: () => void;
  /**
   * The element ref to attach to the input
   */
  elementRef: React.RefObject<HTMLElement | null>;
  /**
   * Get the current value for saving
   */
  getValue: () => T;
};

const defaultIsEqual = <T,>(a: T, b: T): boolean => {
  if (a === b) return true;
  if (a === null || a === undefined || b === null || b === undefined) return false;
  if (typeof a === "object" && typeof b === "object") {
    return JSON.stringify(a) === JSON.stringify(b);
  }
  return false;
};

export function useInlineEdit<T>({
  initialValue,
  currentValue,
  isEqual = defaultIsEqual,
  onChange
}: UseInlineEditOptions<T>): UseInlineEditReturn<T> {
  const [value, setValue] = useState<T>(initialValue);
  const elementRef = useRef<HTMLElement>(null);

  // Sync with currentValue when it changes externally
  useEffect(() => {
    if (currentValue !== undefined && !isEqual(value, currentValue)) {
      // Only sync if we don't have local changes
      // This prevents overwriting user edits
      const hasLocalChanges = !isEqual(value, initialValue);
      if (!hasLocalChanges) {
        setValue(currentValue);
      }
    }
  }, [currentValue, initialValue, isEqual, value]);

  // Update local value when initialValue changes (but not when user is editing)
  useEffect(() => {
    if (!isEqual(value, initialValue) && currentValue === undefined) {
      // User has changes, don't override
      return;
    }
    if (!isEqual(value, initialValue)) {
      // Check if the change is from external update
      return;
    }
    setValue(initialValue);
  }, [initialValue, isEqual, value, currentValue]);

  const handleChange = useCallback((newValue: T) => {
    setValue(newValue);
    onChange?.(newValue);
  }, [onChange]);

  const hasChanges = !isEqual(value, initialValue);

  const reset = useCallback(() => {
    setValue(initialValue);
  }, [initialValue]);

  const sync = useCallback(() => {
    if (currentValue !== undefined) {
      setValue(currentValue);
    } else {
      setValue(initialValue);
    }
  }, [currentValue, initialValue]);

  const getValue = useCallback(() => value, [value]);

  return {
    value,
    setValue: handleChange,
    hasChanges,
    reset,
    sync,
    elementRef,
    getValue
  };
}

"use client";

import { createContext, useContext, useEffect, useMemo, useState } from "react";

import { createTranslator, DEFAULT_LOCALE, normalizeLocale, type Locale } from "../../lib/i18n";

type I18nContextValue = {
  locale: Locale;
  setLocale: (value: Locale | string) => void;
  t: (key: string, params?: Record<string, string | number>) => string;
};

const I18nContext = createContext<I18nContextValue | undefined>(undefined);

const LOCALE_STORAGE_KEY = "audion_locale";
const LOCALE_COOKIE = "audion_locale";
const LOCALE_COOKIE_MAX_AGE = 60 * 60 * 24 * 365;

export const I18nProvider = ({
  children,
  initialLocale,
}: {
  children: React.ReactNode;
  initialLocale?: Locale;
}) => {
  const [locale, setLocaleState] = useState<Locale>(normalizeLocale(initialLocale ?? DEFAULT_LOCALE));

  useEffect(() => {
    if (typeof window === "undefined") return;
    const stored = window.localStorage.getItem(LOCALE_STORAGE_KEY);
    if (stored) {
      setLocaleState(normalizeLocale(stored));
    }
  }, []);

  useEffect(() => {
    if (typeof document === "undefined") return;
    document.documentElement.lang = locale;
    try {
      window.localStorage.setItem(LOCALE_STORAGE_KEY, locale);
    } catch {
      // ignore storage failures
    }
    document.cookie = `${LOCALE_COOKIE}=${locale}; path=/; max-age=${LOCALE_COOKIE_MAX_AGE}; samesite=lax`;
  }, [locale]);

  const setLocale = (value: Locale | string) => {
    setLocaleState(normalizeLocale(String(value)));
  };

  const t = useMemo(() => createTranslator(locale), [locale]);

  const value = useMemo<I18nContextValue>(
    () => ({
      locale,
      setLocale,
      t,
    }),
    [locale, t]
  );

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
};

export const useI18n = () => {
  const context = useContext(I18nContext);
  if (!context) {
    throw new Error("useI18n must be used within I18nProvider");
  }
  return context;
};

