      notify(t("personaAdmin.toasts.knowledgeAdded"));
    } catch (error) {
      console.error("Knowledge add failed", error);
      notify(t("personaAdmin.toasts.knowledgeSaveFailed"));
    } finally {
      setKnowledgePending(false);
    }
  };

