                      })()}
                    </Box>
                  </Box>
                  {detail.profile.bio && (
                    <MsqdxGlassDashboardCardSection title={t("personaAdmin.biography")}>
                      <p style={{ lineHeight: "1.6", whiteSpace: "pre-wrap", margin: 0 }}>
                        {detail.profile.bio}
                      </p>
                    </MsqdxGlassDashboardCardSection>
                  )}
