                    <Box sx={{ borderLeft: "1px solid", borderColor: "divider", pl: 1.5 }}>
                      <MsqdxTypography variant="caption" sx={{ color: "text.secondary", textTransform: "uppercase", letterSpacing: "0.05em", display: "block", mb: 0.25 }}>
