"use client";

import { useCallback, useEffect, useRef, useState } from "react";

type RecognitionConstructor = new () => SpeechRecognitionInstance;

interface SpeechRecognitionAlternative {
  transcript: string;
  confidence: number;
}

interface SpeechRecognitionResult {
  isFinal: boolean;
  length: number;
  item(index: number): SpeechRecognitionAlternative;
  [index: number]: SpeechRecognitionAlternative;
}

interface SpeechRecognitionResultList {
  length: number;
  item(index: number): SpeechRecognitionResult;
  [index: number]: SpeechRecognitionResult;
}

interface SpeechRecognitionEvent {
  resultIndex: number;
  results: SpeechRecognitionResultList;
}

interface SpeechRecognitionErrorEvent {
  error: string;
  message?: string;
}

interface SpeechRecognitionInstance {
  lang: string;
  continuous: boolean;
  interimResults: boolean;
  start: () => void;
  stop: () => void;
  abort: () => void;
  onresult: ((event: SpeechRecognitionEvent) => void) | null;
  onerror: ((event: SpeechRecognitionErrorEvent) => void) | null;
  onend: (() => void) | null;
}

const getRecognitionConstructor = (): RecognitionConstructor | null => {
  if (typeof window === "undefined") {
    return null;
  }

  const globalWindow = window as typeof window & {
    webkitSpeechRecognition?: RecognitionConstructor;
    SpeechRecognition?: RecognitionConstructor;
  };

  return globalWindow.SpeechRecognition ?? globalWindow.webkitSpeechRecognition ?? null;
};

export const useSpeechToText = () => {
  const recognitionRef = useRef<SpeechRecognitionInstance | null>(null);
  const [supported, setSupported] = useState(false);
  const [listening, setListening] = useState(false);
  const [transcript, setTranscript] = useState("");
  const [error, setError] = useState<string | null>(null);

  const ensureRecognition = useCallback(() => {
    if (recognitionRef.current) {
      return recognitionRef.current;
    }

    const RecognitionCtor = getRecognitionConstructor();
    if (!RecognitionCtor) {
      return null;
    }

    const recognition = new RecognitionCtor();
    recognition.continuous = true;
    recognition.interimResults = true;
    recognition.lang = typeof navigator !== "undefined" ? navigator.language ?? "en-US" : "en-US";
    recognition.onresult = (event) => {
      let latestTranscript = "";
      for (let i = event.resultIndex; i < event.results.length; i += 1) {
        const result = event.results[i];
        latestTranscript += result[0]?.transcript ?? "";
      }
      setTranscript(latestTranscript.trim());
    };
    recognition.onerror = (event) => {
      const errorCode = event.error ?? "";
      let userMessage = "Speech recognition error";

      if (errorCode === "not-allowed" || errorCode === "no-speech") {
        userMessage = "Microphone permission denied. Please allow microphone access in your browser settings.";
      } else if (errorCode === "aborted") {
        // Don't show error for aborted - it's usually intentional
        setListening(false);
        return;
      } else if (errorCode === "network") {
        userMessage = "Cannot connect to speech recognition service. Please check your internet connection. The Web Speech API requires an active internet connection to Google's speech recognition service.";
      } else if (errorCode === "audio-capture") {
        userMessage = "No microphone found. Please connect a microphone.";
      } else if (errorCode === "service-not-allowed") {
        userMessage = "Speech recognition service is not available. Please check your browser settings or try again later.";
      } else if (errorCode === "bad-grammar") {
        userMessage = "Speech recognition grammar error.";
      } else if (errorCode === "language-not-supported") {
        userMessage = "The selected language is not supported for speech recognition.";
      } else if (errorCode) {
        userMessage = `Speech recognition error: ${errorCode}`;
      }

      setError(userMessage);
      setListening(false);
    };
    recognition.onend = () => {
      setListening(false);
    };

    recognitionRef.current = recognition;
    setSupported(true);
    return recognition;
  }, []);

  useEffect(() => {
    ensureRecognition();
    return () => {
      recognitionRef.current?.stop();
      recognitionRef.current = null;
    };
  }, [ensureRecognition]);

  const startListening = useCallback(async (): Promise<boolean> => {
    setError(null);
    const recognition = ensureRecognition();
    if (!recognition) {
      setSupported(false);
      setError("Speech recognition is not supported in this browser.");
      return false;
    }

    // Check if mediaDevices API is available
    if (typeof navigator === "undefined" || !navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      // If not available, try to start recognition directly (some browsers handle permissions differently)
      try {
        recognition.start();
        setListening(true);
        setTranscript("");
        return true;
      } catch (err) {
        const error = err as Error;
        if (error.message.includes("not-allowed") || error.message.includes("permission")) {
          setError("Microphone permission denied. Please allow microphone access in your browser settings. Note: HTTPS is required for microphone access.");
        } else {
          setError(`Failed to start speech recognition: ${error.message}`);
        }
        setListening(false);
        return false;
      }
    }

    // Request microphone permission first
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      // Stop the stream immediately - we just needed permission
      stream.getTracks().forEach((track) => track.stop());
    } catch (err) {
      const error = err as Error;
      if (error.name === "NotAllowedError" || error.name === "PermissionDeniedError") {
        setError("Microphone permission denied. Please allow microphone access in your browser settings.");
      } else if (error.name === "NotFoundError" || error.name === "DevicesNotFoundError") {
        setError("No microphone found. Please connect a microphone.");
      } else if (error.name === "NotSupportedError" || error.name === "NotReadableError") {
        setError("Microphone access is not available. Please ensure you're using HTTPS or localhost.");
      } else {
        setError(`Failed to access microphone: ${error.message || "Unknown error"}`);
      }
      setListening(false);
      return false;
    }

    try {
      recognition.start();
      setListening(true);
      setTranscript("");
      return true;
    } catch (err) {
      const error = err as Error;
      if (error.message.includes("already started") || error.message.includes("started")) {
        // Recognition is already running, try to stop and restart
        try {
          recognition.stop();
          await new Promise((resolve) => setTimeout(resolve, 100));
          recognition.start();
          setListening(true);
          setTranscript("");
          return true;
        } catch (retryErr) {
          setError((retryErr as Error).message);
          setListening(false);
          return false;
        }
      }
      setError(error.message || "Failed to start speech recognition.");
      setListening(false);
      return false;
    }
  }, [ensureRecognition]);

  const stopListening = useCallback(() => {
    recognitionRef.current?.stop();
  }, []);

  const resetTranscript = useCallback(() => {
    setTranscript("");
  }, []);

  return {
    supported,
    listening,
    transcript,
    error,
    startListening,
    stopListening,
    resetTranscript
  };
};

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

interface TranscriptionResult {
  text: string;
  language?: string;
  language_probability?: number;
}

interface UseWhisperTranscriptionOptions {
  onTranscriptionComplete?: (text: string) => void;
}

export const useWhisperTranscription = (options?: UseWhisperTranscriptionOptions) => {
  const [recording, setRecording] = useState(false);
  const [transcribing, setTranscribing] = useState(false);
  const [transcript, setTranscript] = useState("");
  const [error, setError] = useState<string | null>(null);
  const onTranscriptionCompleteRef = useRef(options?.onTranscriptionComplete);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const streamRef = useRef<MediaStream | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const vadIntervalRef = useRef<number | null>(null);
  const silenceStartRef = useRef<number | null>(null);
  const maxRecordingTimeRef = useRef<number | null>(null);

  // Update callback ref when options change
  useEffect(() => {
    onTranscriptionCompleteRef.current = options?.onTranscriptionComplete;
  }, [options?.onTranscriptionComplete]);

  const startRecording = useCallback(async (): Promise<boolean> => {
    try {
      setError(null);
      setTranscript("");

      // Request microphone access
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;

      // Create AudioContext for VAD
      const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
      audioContextRef.current = audioContext;

      const source = audioContext.createMediaStreamSource(stream);
      const analyser = audioContext.createAnalyser();
      analyser.fftSize = 2048;
      analyser.smoothingTimeConstant = 0.8;
      source.connect(analyser);
      analyserRef.current = analyser;

      // Create MediaRecorder
      const mediaRecorder = new MediaRecorder(stream, {
        mimeType: MediaRecorder.isTypeSupported("audio/webm") 
          ? "audio/webm" 
          : MediaRecorder.isTypeSupported("audio/mp4")
          ? "audio/mp4"
          : "audio/wav"
      });

      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];
      silenceStartRef.current = null;

      mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) {
          audioChunksRef.current.push(event.data);
        }
      };

      mediaRecorder.onstop = async () => {
        // Clean up VAD
        if (vadIntervalRef.current) {
          clearInterval(vadIntervalRef.current);
          vadIntervalRef.current = null;
        }
        if (maxRecordingTimeRef.current) {
          clearTimeout(maxRecordingTimeRef.current);
          maxRecordingTimeRef.current = null;
        }
        if (audioContextRef.current) {
          await audioContextRef.current.close();
          audioContextRef.current = null;
        }
        analyserRef.current = null;

        // Stop all tracks
        streamRef.current?.getTracks().forEach((track) => track.stop());
        streamRef.current = null;

        // Transcribe audio
        if (audioChunksRef.current.length > 0) {
          await transcribeAudio();
        }
      };

      // Start VAD monitoring
      const startVAD = () => {
        const dataArray = new Uint8Array(analyser.frequencyBinCount);
        const SILENCE_THRESHOLD = 20; // Adjust based on testing (0-255)
        const SILENCE_DURATION = 2000; // 2 seconds of silence before stopping
        const MAX_RECORDING_TIME = 30000; // 30 seconds max

        // Set max recording time
        maxRecordingTimeRef.current = window.setTimeout(() => {
          if (mediaRecorderRef.current && mediaRecorderRef.current.state === "recording") {
            mediaRecorderRef.current.stop();
            setRecording(false);
          }
        }, MAX_RECORDING_TIME);

        // Monitor audio levels
        vadIntervalRef.current = window.setInterval(() => {
          if (!analyserRef.current || !mediaRecorderRef.current) {
            return;
          }

          analyser.getByteFrequencyData(dataArray);

          // Calculate average volume
          const average = dataArray.reduce((sum, value) => sum + value, 0) / dataArray.length;

          if (average > SILENCE_THRESHOLD) {
            // Voice detected, reset silence timer
            silenceStartRef.current = null;
          } else {
            // Silence detected
            const now = Date.now();
            if (silenceStartRef.current === null) {
              silenceStartRef.current = now;
            } else if (now - silenceStartRef.current >= SILENCE_DURATION) {
              // Silence for long enough, stop recording
              if (mediaRecorderRef.current && mediaRecorderRef.current.state === "recording") {
                mediaRecorderRef.current.stop();
                setRecording(false);
              }
            }
          }
        }, 100); // Check every 100ms
      };

      mediaRecorder.start();
      setRecording(true);

      // Start VAD after a short delay to avoid false positives
      setTimeout(startVAD, 500);

      return true;
    } catch (err) {
      const error = err as Error;
      if (error.name === "NotAllowedError" || error.name === "PermissionDeniedError") {
        setError("Microphone permission denied. Please allow microphone access in your browser settings.");
      } else if (error.name === "NotFoundError" || error.name === "DevicesNotFoundError") {
        setError("No microphone found. Please connect a microphone.");
      } else {
        setError(`Failed to start recording: ${error.message}`);
      }
      setRecording(false);
      return false;
    }
  }, []);

  const stopRecording = useCallback(() => {
    if (mediaRecorderRef.current && mediaRecorderRef.current.state === "recording") {
      // Clean up VAD
      if (vadIntervalRef.current) {
        clearInterval(vadIntervalRef.current);
        vadIntervalRef.current = null;
      }
      if (maxRecordingTimeRef.current) {
        clearTimeout(maxRecordingTimeRef.current);
        maxRecordingTimeRef.current = null;
      }

      mediaRecorderRef.current.stop();
      setRecording(false);
    }
  }, []);

  const transcribeAudio = useCallback(async () => {
    if (audioChunksRef.current.length === 0) {
      setError("No audio recorded");
      return;
    }

    try {
      setTranscribing(true);
      setError(null);

      // Combine audio chunks into a single blob
      const audioBlob = new Blob(audioChunksRef.current, {
        type: mediaRecorderRef.current?.mimeType || "audio/webm"
      });

      // Create FormData
      const formData = new FormData();
      formData.append("audio", audioBlob, "recording.webm");

      // Get API base URL - use relative path for nginx routing
      // nginx routes /api/voice to chat-api service
      const apiUrl = "/api/voice/transcribe";

      // Send to server
      const response = await fetch(apiUrl, {
        method: "POST",
        body: formData,
      });

      if (!response.ok) {
        const errorText = await response.text().catch(() => "Unknown error");
        throw new Error(`Transcription failed: ${errorText}`);
      }

      const result: TranscriptionResult = await response.json();
      const transcribedText = result.text || "";
      setTranscript(transcribedText);

      // Call callback if provided
      if (onTranscriptionCompleteRef.current && transcribedText.trim()) {
        onTranscriptionCompleteRef.current(transcribedText);
      }
    } catch (err) {
      const error = err as Error;
      setError(`Transcription failed: ${error.message}`);
      setTranscript("");
    } finally {
      setTranscribing(false);
      audioChunksRef.current = [];
    }
  }, []);

  const resetTranscript = useCallback(() => {
    setTranscript("");
    setError(null);
  }, []);

  return {
    recording,
    transcribing,
    transcript,
    error,
    startRecording,
    stopRecording,
    resetTranscript,
  };
};

import type { PhaseResponse } from "../app/api/_lib/journeys";

export type Message = {
  id: string;
  role: "user" | "persona" | "system";
  content: string;
  personaName?: string;
};

// PersonaProfile type - matches the structure used in chat page
export type PersonaProfile = {
  name?: string | null;
  fullName?: string | null;
  headline?: string | null;
  bio?: string | null;
  age?: number | null;
  location?: string | null;
  gender?: string | null;
  media_affinity?: number | null;
  interests?: string[];
  colorPalette?: string[];
  attentionSpan?: string | null;
  socialMediaUsage?: string[];
  values?: string[];
  traits?: Record<string, number>;
  painPoints?: Array<{ label?: string; evidenceCount?: number }>;
  goals?: Array<{ label?: string; priority?: number }>;
  communicationStyle?: {
    vocabulary?: string[];
    sentenceStructure?: string;
    skepticismLevel?: number;
  };
};

export type ConversationLearning = {
  id: string;
  personaId?: string; // undefined = global learning
  topic: string;
  userPreference?: string;
  personaInsight?: string;
  extractedFrom: string; // Message-ID oder Kontext
  timestamp: Date;
  confidence?: number; // 0-1, wie sicher sind wir bei diesem Learning
};

export type PromptContext = {
  persona: PersonaProfile;
  journeyPhases?: PhaseResponse[];
  conversationHistory: Message[];
  learnings: ConversationLearning[];
  currentPhase?: PhaseResponse;
  messageCount: number;
  baseSystemPrompt?: string | null; // Optional: Base system prompt from database
};

/**
 * Extrahiert Hauptthemen aus dem Gesprächsverlauf
 */
export function extractTopics(messages: Message[]): string[] {
  const topics: string[] = [];
  const userMessages = messages.filter((m) => m.role === "user");

  // Einfache Keyword-basierte Erkennung
  const topicKeywords: Record<string, string[]> = {
    product: ["product", "feature", "functionality", "capability"],
    pricing: ["price", "cost", "pricing", "expensive", "cheap", "affordable"],
    support: ["help", "support", "issue", "problem", "error", "bug"],
    onboarding: ["getting started", "setup", "tutorial", "guide", "onboarding"],
    integration: ["integrate", "api", "connect", "sync", "import"],
  };

  const foundTopics = new Set<string>();

  userMessages.forEach((msg) => {
    const content = msg.content.toLowerCase();
    Object.entries(topicKeywords).forEach(([topic, keywords]) => {
      if (keywords.some((keyword) => content.includes(keyword))) {
        foundTopics.add(topic);
      }
    });
  });

  return Array.from(foundTopics);
}

/**
 * Generiert adaptive Anweisungen basierend auf Gesprächsphase
 */
export function buildAdaptiveInstructions(context: PromptContext): string {
  const { conversationHistory, learnings, currentPhase, messageCount } = context;

  let instructions = `Instructions:\n`;
  instructions += `- Always stay in character as this persona - never break character or refer to yourself as an AI\n`;
  instructions += `- Respond from the persona's perspective, using their voice, knowledge, and experiences\n`;
  instructions += `- Think and react as this persona would, not as an external observer\n`;

  // Wenn das Gespräch gerade beginnt
  if (messageCount < 3) {
    instructions += `- Start with a warm, engaging greeting\n`;
    instructions += `- Ask open-ended questions to understand the user's needs\n`;
    instructions += `- Be conversational and approachable\n`;
  } else if (messageCount < 6) {
    // Mittlere Phase
    instructions += `- Reference previous conversation points naturally\n`;
    instructions += `- Build on established context\n`;
    instructions += `- Deepen the conversation based on what you've learned\n`;
  } else {
    // Fortgeschrittene Phase
    instructions += `- Reference previous conversation points naturally\n`;
    instructions += `- Build on established context\n`;
    instructions += `- Provide detailed, specific responses based on the conversation history\n`;
  }

  // Journey-Phase-spezifische Anweisungen
  if (currentPhase) {
    if (currentPhase.description) {
      instructions += `- Current phase goal: ${currentPhase.description}\n`;
    }
    if (currentPhase.expected_emotion) {
      instructions += `- Expected user emotion: ${currentPhase.expected_emotion}\n`;
    }
  }

  // Learning-basierte Anweisungen
  if (learnings.length > 0) {
    const userPreferences = learnings.filter((l) => l.userPreference);
    if (userPreferences.length > 0) {
      instructions += `- Adapt your communication style based on user preferences\n`;
      instructions += `- Use insights from previous interactions\n`;
    }
  }

  return instructions;
}

/**
 * Ersetzt Variablen im Prompt durch tatsächliche Werte aus dem Persona-Profil
 */
function replacePromptVariables(prompt: string, persona: PersonaProfile): string {
  // Erstelle ein Mapping aller verfügbaren Variablen
  const variables: Record<string, string> = {
    // Basis-Informationen
    persona_name: persona.name || persona.fullName || "",
    persona_fullname: persona.fullName || persona.name || "",
    persona_headline: persona.headline || "",
    persona_bio: persona.bio || "",
    persona_age: persona.age?.toString() || "",
    persona_location: persona.location || "",
    persona_gender: persona.gender || "",
    persona_media_affinity: persona.media_affinity?.toString() || "",
    persona_attention_span: persona.attentionSpan || "",

    // Arrays als komma-separierte Listen
    persona_interests: persona.interests?.join(", ") || "",
    persona_values: persona.values?.join(", ") || "",
    persona_color_palette: persona.colorPalette?.join(", ") || "",
    persona_social_media_usage: persona.socialMediaUsage?.join(", ") || "",

    // Communication Style
    persona_vocabulary: persona.communicationStyle?.vocabulary?.join(", ") || "",
    persona_sentence_structure: persona.communicationStyle?.sentenceStructure || "",
    persona_skepticism_level: persona.communicationStyle?.skepticismLevel?.toString() || "",

    // Pain Points
    persona_pain_points: persona.painPoints?.map(p => p.label || "").filter(Boolean).join(", ") || "",

    // Goals
    persona_goals: persona.goals?.map(g => g.label || "").filter(Boolean).join(", ") || "",

    // Traits
    persona_traits: persona.traits ? Object.entries(persona.traits)
      .map(([key, value]) => `${key}: ${value}`)
      .join(", ") : "",
    existing_traits: persona.traits ? Object.entries(persona.traits)
      .map(([key, value]) => `${key}: ${value}`)
      .join(", ") : "",
  };

  // Ersetze alle Variablen im Format ${variable_name}
  let replacedPrompt = prompt;
  const variablePattern = /\$\{([^}]+)\}/g;

  // Finde alle Variablen im Prompt
  const foundVariables = [...prompt.matchAll(variablePattern)];

  replacedPrompt = replacedPrompt.replace(variablePattern, (match, variableName) => {
    const trimmedName = variableName.trim();
    const normalizedName = trimmedName.toLowerCase();

    // Suche nach exakter Übereinstimmung (case-insensitive)
    const exactMatch = Object.entries(variables).find(([key]) => 
      key.toLowerCase() === normalizedName
    );

    if (exactMatch) {
      const value = exactMatch[1];
      // Debug für wichtige Variablen
      if (trimmedName.toLowerCase() === "persona_headline" || trimmedName.toLowerCase() === "persona_bio") {
        console.log(`[replacePromptVariables] Replacing ${trimmedName} with:`, value.substring(0, 100));
      }
      return value;
    }

    // Versuche mit Unterstrichen statt Bindestrichen
    const altName = normalizedName.replace(/-/g, "_");
    const altMatch = Object.entries(variables).find(([key]) => 
      key.toLowerCase() === altName
    );

    if (altMatch) {
      return altMatch[1];
    }

    // Debug: Log nicht gefundene Variablen
    console.warn(`[replacePromptVariables] Variable not found: ${trimmedName}`, {
      availableVariables: Object.keys(variables),
      normalizedName,
      altName,
    });

    // Wenn nicht gefunden, gib die Variable zurück (nicht ersetzt)
    return match;
  });

  return replacedPrompt;
}

/**
 * Baut den adaptiven System-Prompt dynamisch zusammen
 */
export function buildAdaptiveSystemPrompt(context: PromptContext): string {
  const { persona, journeyPhases, conversationHistory, learnings, currentPhase, baseSystemPrompt } = context;

  // Wenn ein Base-System-Prompt aus der Datenbank vorhanden ist, verwende ihn als Basis
  let prompt = "";

  if (baseSystemPrompt && baseSystemPrompt.trim().length > 0) {
    // Verwende den System-Prompt aus der Datenbank als Basis
    prompt = baseSystemPrompt.trim();

    // Ersetze Variablen durch tatsächliche Werte
    const beforeReplace = prompt;
    const variablesInPrompt = beforeReplace.match(/\$\{([^}]+)\}/g) || [];
    prompt = replacePromptVariables(prompt, persona);

    // Debug: Log variable replacement (always, not just for Clara)
    console.log("[AdaptivePrompt] Variable replacement:", {
      personaName: persona.name,
      hasVariables: beforeReplace.includes("${"),
      variablesFound: variablesInPrompt,
      beforeReplace: beforeReplace.substring(0, 400),
      afterReplace: prompt.substring(0, 400),
      personaData: {
        name: persona.name,
        headline: persona.headline,
        bio: persona.bio?.substring(0, 100),
        fullName: persona.fullName,
      },
    });

    // WICHTIG: Füge explizite Anweisung hinzu, sich in die Persona hineinzuversetzen
    // Dies wird am Anfang hinzugefügt, damit es die höchste Priorität hat
    const personaIdentityInstruction = `You are ${persona.name || persona.fullName || "this persona"}. You must fully embody and act as this persona. Think, speak, and respond exactly as this persona would - not as an AI assistant describing the persona, but AS the persona themselves. Immerse yourself completely in this role and maintain this identity throughout the entire conversation.\n\n`;

    prompt = personaIdentityInstruction + prompt;
  } else {
    // Fallback: Baue Prompt dynamisch aus Persona-Profil (alte Logik)
    // WICHTIG: Explizite Anweisung, sich in die Persona hineinzuversetzen
    prompt = `You are ${persona.name || persona.fullName || "this persona"}. You must fully embody and act as this persona. Think, speak, and respond exactly as this persona would - not as an AI assistant describing the persona, but AS the persona themselves. Immerse yourself completely in this role and maintain this identity throughout the entire conversation.\n\n`;

    // Basis-Persona-Informationen
    if (persona.bio) {
      prompt += `About you: ${persona.bio}\n\n`;
    }

    if (persona.headline) {
      prompt += `Headline: ${persona.headline}\n\n`;
    }

    // Demografische Informationen
    const demographics: string[] = [];
    if (persona.age) {
      demographics.push(`Age: ${persona.age}`);
    }
    if (persona.location) {
      demographics.push(`Location: ${persona.location}`);
    }
    if (persona.gender) {
      demographics.push(`Gender: ${persona.gender}`);
    }
    if (demographics.length > 0) {
      prompt += `Demographics: ${demographics.join(", ")}\n\n`;
    }

    // Communication Style
    if (persona.communicationStyle) {
      prompt += `Communication style:\n`;
      if (persona.communicationStyle.vocabulary && persona.communicationStyle.vocabulary.length > 0) {
        prompt += `- Vocabulary: ${persona.communicationStyle.vocabulary.join(", ")}\n`;
      }
      if (persona.communicationStyle.sentenceStructure) {
        prompt += `- Sentence structure: ${persona.communicationStyle.sentenceStructure}\n`;
      }
      if (persona.communicationStyle.skepticismLevel !== undefined) {
        prompt += `- Skepticism level: ${persona.communicationStyle.skepticismLevel}/10\n`;
      }
      prompt += `\n`;
    }

    // Traits (Persönlichkeitsmerkmale)
    if (persona.traits && Object.keys(persona.traits).length > 0) {
      prompt += `Personality traits:\n`;
      Object.entries(persona.traits).forEach(([trait, value]) => {
        prompt += `- ${trait}: ${value}/10\n`;
      });
      prompt += `\n`;
    }

    // Pain Points (Frustrationen/Probleme)
    if (persona.painPoints && persona.painPoints.length > 0) {
      prompt += `Pain points and frustrations:\n`;
      persona.painPoints.forEach((pp) => {
        const label = pp.label || "";
        const evidence = pp.evidenceCount ? ` (${pp.evidenceCount} evidence)` : "";
        prompt += `- ${label}${evidence}\n`;
      });
      prompt += `\n`;
    }

    // Goals (Ziele)
    if (persona.goals && persona.goals.length > 0) {
      prompt += `Goals and aspirations:\n`;
      persona.goals.forEach((goal) => {
        const label = goal.label || "";
        const priority = goal.priority ? ` (Priority: ${goal.priority})` : "";
        prompt += `- ${label}${priority}\n`;
      });
      prompt += `\n`;
    }

    // Interests
    if (persona.interests && persona.interests.length > 0) {
      prompt += `Interests: ${persona.interests.join(", ")}\n\n`;
    }

    // Values
    if (persona.values && persona.values.length > 0) {
      prompt += `Values: ${persona.values.join(", ")}\n\n`;
    }

    // Media Affinity & Attention Span
    if (persona.media_affinity !== null && persona.media_affinity !== undefined) {
      prompt += `Media affinity: ${persona.media_affinity}/10\n`;
    }
    if (persona.attentionSpan) {
      prompt += `Attention span: ${persona.attentionSpan}\n`;
    }
    if (persona.media_affinity !== null || persona.attentionSpan) {
      prompt += `\n`;
    }

    // Social Media Usage
    if (persona.socialMediaUsage && persona.socialMediaUsage.length > 0) {
      prompt += `Social media usage: ${persona.socialMediaUsage.join(", ")}\n\n`;
    }

    // Color Palette (Design-Präferenzen)
    if (persona.colorPalette && persona.colorPalette.length > 0) {
      prompt += `Preferred color palette: ${persona.colorPalette.join(", ")}\n\n`;
    }

    // Journey-Kontext (wenn vorhanden)
    if (currentPhase) {
      prompt += `Current conversation phase: ${currentPhase.name}\n`;
      if (currentPhase.description) {
        prompt += `Phase goal: ${currentPhase.description}\n`;
      }
      if (currentPhase.expected_emotion) {
        prompt += `Expected emotion: ${currentPhase.expected_emotion}\n`;
      }
      prompt += `\n`;
    } else if (journeyPhases && journeyPhases.length > 0) {
      prompt += `Available journey phases: ${journeyPhases.map((p) => p.name).join(", ")}\n\n`;
    }

    // Learnings aus vorherigen Gesprächen
    if (learnings.length > 0) {
      prompt += `Conversation insights:\n`;
      learnings.forEach((learning) => {
        if (learning.userPreference) {
          prompt += `- User prefers: ${learning.userPreference}\n`;
        }
        if (learning.personaInsight) {
          prompt += `- Insight: ${learning.personaInsight}\n`;
        }
      });
      prompt += `\n`;
    }

    // Gesprächsverlauf-Analyse (letzte N Nachrichten)
    if (conversationHistory.length > 0) {
      const topics = extractTopics(conversationHistory);
      if (topics.length > 0) {
        prompt += `Recent conversation topics: ${topics.join(", ")}\n\n`;
      }
    }

    // Adaptive Anweisungen
    prompt += buildAdaptiveInstructions(context);
  }

  return prompt;
}

/**
 * Shared utilities for brand color selection.
 * Used by BrandColorSelector, login/register pages, and admin layout.
 */

export const BRAND_COLOR_STORAGE_KEY = "audion-sidebar-color";
export const BRAND_COLOR_DEFAULT = "--color-secondary-dx-green";

/** Farben, auf denen Text/Icons schwarz statt weiß sein müssen (helle Hintergründe) */
export const LIGHT_ACCENT_COLORS = [
  "--color-secondary-dx-yellow",
  "--color-secondary-dx-grey-light",
  "--color-secondary-dx-green",
] as const;

export function isLightAccentColor(varName: string): boolean {
  return (LIGHT_ACCENT_COLORS as readonly string[]).includes(varName);
}

const OPTIONS_META: {
  varName: string;
  preview: string;
  textColor: string;
}[] = [
  { varName: "--color-secondary-dx-purple", preview: "#b638ff", textColor: "#ffffff" },
  { varName: "--color-secondary-dx-blue", preview: "#3b82f6", textColor: "#ffffff" },
  { varName: "--color-secondary-dx-pink", preview: "#f256b6", textColor: "#ffffff" },
  { varName: "--color-secondary-dx-orange", preview: "#ff6a3b", textColor: "#ffffff" },
  { varName: "--color-secondary-dx-green", preview: "#00ca55", textColor: "#000000" },
  { varName: "--color-secondary-dx-yellow", preview: "#fef14d", textColor: "#000000" },
  { varName: "--color-secondary-dx-grey-light", preview: "#d4d2d2", textColor: "#000000" },
  { varName: "--audion-light-border-color", preview: "#0f172a", textColor: "#ffffff" },
];

const COLOR_TINT_MAP: Record<string, string> = {
  "--color-secondary-dx-purple": "--color-secondary-dx-purple-tint",
  "--color-secondary-dx-blue": "--color-secondary-dx-blue-tint",
  "--color-secondary-dx-pink": "--color-secondary-dx-pink-tint",
  "--color-secondary-dx-orange": "--color-secondary-dx-orange-tint",
  "--color-secondary-dx-green": "--color-secondary-dx-green-tint",
  "--color-secondary-dx-yellow": "--color-secondary-dx-yellow-tint",
  "--color-secondary-dx-grey-light": "--color-secondary-dx-grey-light-tint",
  "--audion-light-border-color": "--color-secondary-dx-purple-tint",
};

export function applyBrandColorVars(
  varName: string,
  themeMode: "light" | "dark"
): void {
  if (typeof document === "undefined") return;

  const styles = getComputedStyle(document.documentElement);
  const resolvedColor =
    styles.getPropertyValue(varName).trim() ||
    (varName === "--audion-light-border-color" ? "#0f172a" : "");

  if (resolvedColor) {
    document.documentElement.style.setProperty(
      "--audion-light-border-color",
      resolvedColor
    );
    document.documentElement.style.setProperty(
      "--audion-light-html-background-color",
      resolvedColor
    );

    /* Text auf Sidebar/Accent: schwarz bei gelb, grau, grün; weiß bei dunklen Farben */
    const textOnAccentColor = OPTIONS_META.find((o) => o.varName === varName)?.textColor || "#ffffff";
    const isLight = textOnAccentColor === "#000000";
    document.documentElement.style.setProperty(
      "--audion-sidebar-text-color",
      textOnAccentColor
    );
    document.documentElement.style.setProperty(
      "--color-theme-accent-contrast",
      textOnAccentColor
    );
    /* Hover/Active auf Sidebar: dunkler Overlay bei hellem Hintergrund, heller bei dunklem */
    document.documentElement.style.setProperty(
      "--audion-sidebar-hover-bg",
      isLight ? "rgba(0, 0, 0, 0.08)" : "rgba(255, 255, 255, 0.1)"
    );
    document.documentElement.style.setProperty(
      "--audion-sidebar-active-bg",
      isLight ? "rgba(0, 0, 0, 0.15)" : "rgba(255, 255, 255, 0.15)"
    );

    document.documentElement.style.setProperty(
      "--color-theme-accent",
      `var(${varName})`
    );

    const tintVar =
      COLOR_TINT_MAP[varName] || "--color-secondary-dx-purple-tint";
    document.documentElement.style.setProperty(
      "--color-theme-accent-tint",
      `var(${tintVar})`
    );

    /* Auth (Login/Register): Logo und Button-Text auf Accent-Hintergrund */
    const textOnAccent = textOnAccentColor;
    document.documentElement.style.setProperty("--auth-logo-color", textOnAccent);
    document.documentElement.style.setProperty(
      "--auth-button-text-color",
      textOnAccent
    );

    /* Input Labels: schwarz bei gelb und hellgrau (bessere Lesbarkeit), sonst Theme-Akzent */
    const labelShouldBeBlack =
      varName === "--color-secondary-dx-yellow" ||
      varName === "--color-secondary-dx-grey-light";
    document.documentElement.style.setProperty(
      "--color-input-label",
      labelShouldBeBlack ? "#000000" : "var(--color-theme-accent)"
    );
  }
}

/** Initializes brand color from localStorage. Call on admin layout mount. */
export function initBrandColorFromStorage(
  themeMode: "light" | "dark"
): void {
  const saved =
    typeof localStorage !== "undefined"
      ? localStorage.getItem(BRAND_COLOR_STORAGE_KEY)
      : null;
  const colorVar = saved || BRAND_COLOR_DEFAULT;
  applyBrandColorVars(colorVar, themeMode);
}

// Stream processor isolated from component to avoid closure issues

export interface StreamCallbacks {
  onDelta: (delta: string) => void;
  onSources: (sources: Array<{
    chunk_id: string;
    document_id: string;
    title: string;
    confidence: number;
    excerpt: string;
  }>) => void;
  onAudioChunk?: (audio: string, mimeType: string) => void;
  onComplete: () => void;
  onError: (error: string) => void;
  setSending: (sending: boolean) => void;
  setThinkingLabel: (label: string | undefined) => void;
}

export async function processStream(
  reader: ReadableStreamDefaultReader<Uint8Array>,
  callbacks: StreamCallbacks
): Promise<string | null> {
  const decoder = new TextDecoder();
  let buffer = "";
  let hasReceivedData = false;
  let streamStarted = false;
  let streamError: string | null = null;

  while (true) {
    const readResult = await reader.read();
    if (readResult.done) {
      if (!hasReceivedData) {
        streamError = "Stream ended without any data";
      }
      break;
    }

    hasReceivedData = true;
    buffer += decoder.decode(readResult.value, { stream: true });
    const lines = buffer.split("\n\n");
    buffer = lines.pop() || "";

    for (const line of lines) {
      if (!line.trim()) continue;
      if (!line.startsWith("data: ")) continue;

      let parsedData: any = null;
      const jsonStr = line.slice(6);
      try {
        parsedData = JSON.parse(jsonStr);
      } catch {
        continue;
      }

      if (!parsedData) continue;

      if (!streamStarted) {
        streamStarted = true;
        callbacks.setSending(false);
      }

      if (parsedData.type === "delta") {
        if (parsedData.delta) {
          callbacks.onDelta(parsedData.delta);
        }
        if (callbacks.onAudioChunk && parsedData.audio) {
          callbacks.onAudioChunk(parsedData.audio, parsedData.mime_type ?? "audio/mpeg");
        }
      } else if (parsedData.type === "sources") {
        const normalizedSources = (parsedData.sources || []).map((source: any, index: number) => ({
          chunk_id: source.chunk_id ?? `chunk-${index}`,
          document_id: source.document_id ?? "Unknown",
          title: source.title ?? "Research",
          confidence: typeof source.confidence === "number" ? source.confidence : 0.8,
          excerpt: source.content ?? "",
        }));
        callbacks.onSources(normalizedSources);
      } else if (parsedData.type === "complete") {
        callbacks.onComplete();
      } else if (parsedData.type === "error") {
        const errVal = parsedData.error;
        streamError = typeof errVal === "string" ? errVal : String(errVal || "Failed to get response");
        break;
      }
    }

    if (streamError) {
      break;
    }
  }

  return streamError;
}

/**
 * This script suppresses errors from browser extensions and Next.js HMR WebSocket connections.
 * It must be loaded early, before extensions inject their content scripts.
 */
(function () {
  "use strict";

  // Filter function to check if error is from browser extension or HMR WebSocket
  function isExtensionError(message, source, stack) {
    const allText = `${message || ""} ${source || ""} ${stack || ""}`.toLowerCase();

    const extensionIndicators = [
      "content_script.js",
      "extension://",
      "moz-extension://",
      "chrome-extension://",
      "safari-extension://",
      "edge-extension://",
      "shouldOfferCompletionListField",
      "shouldOfferCompletionListForField",
      "elementWasFocused",
      "focusInEventHandler",
      "processInputEvent",
      "inputEventHandler",
      "cannot read properties of undefined (reading 'control')",
      "control",
      "autofill",
      "password-manager",
    ];

    const hmrIndicators = [
      "websocket connection",
      "webpack-hmr",
      "webpack hmr",
      "failed to connect",
      "connection failed",
      "_next/webpack-hmr",
      "web-socket.js",
      "webpack.js",
    ];

    return (
      extensionIndicators.some(function (indicator) {
        return allText.includes(indicator.toLowerCase());
      }) ||
      hmrIndicators.some(function (indicator) {
        return allText.includes(indicator.toLowerCase());
      })
    );
  }

  // Store original console methods
  const originalConsoleError = console.error;
  const originalConsoleWarn = console.warn;
  const originalConsoleLog = console.log;

  // Override console.error
  console.error = function () {
    const args = Array.prototype.slice.call(arguments);
    const message = args.map(function (arg) {
      return String(arg);
    }).join(" ");

    // Check if it's an extension error or HMR WebSocket error
    if (isExtensionError(message)) {
      return; // Silently ignore extension errors
    }

    // Also check for WebSocket connection errors in the message
    if (message.includes("WebSocket connection") && 
        (message.includes("webpack-hmr") || message.includes("_next/webpack-hmr") || message.includes("failed"))) {
      return; // Silently ignore HMR WebSocket connection errors
    }

    originalConsoleError.apply(console, arguments);
  };

  // Override console.warn
  console.warn = function () {
    const args = Array.prototype.slice.call(arguments);
    const message = args.map(function (arg) {
      return String(arg);
    }).join(" ");

    if (isExtensionError(message)) {
      return; // Silently ignore extension warnings
    }

    originalConsoleWarn.apply(console, arguments);
  };

  // Override window.onerror (must be done early)
  const originalOnError = window.onerror;
  window.onerror = function (message, source, lineno, colno, error) {
    if (isExtensionError(message, source, error && error.stack)) {
      return true; // Suppress extension errors
    }

    if (originalOnError) {
      return originalOnError(message, source, lineno, colno, error);
    }

    return false;
  };

  // Handle unhandled promise rejections
  window.addEventListener(
    "unhandledrejection",
    function (event) {
      const reason = event.reason;
      const message =
        (reason && reason.message) || String(reason || "");

      if (isExtensionError(message)) {
        event.preventDefault();
        event.stopPropagation();
        return;
      }
    },
    true // Use capture phase
  );

  // Handle errors via error event listener
  window.addEventListener(
    "error",
    function (event) {
      if (
        isExtensionError(
          event.message,
          event.filename,
          event.error && event.error.stack
        )
      ) {
        event.preventDefault();
        event.stopPropagation();
        return false;
      }
    },
    true // Use capture phase
  );

  // Suppress WebSocket connection errors from Next.js HMR
  // This prevents console spam when HMR WebSocket connections fail
  const originalWebSocket = window.WebSocket;
  window.WebSocket = function (url, protocols) {
    const urlString = String(url || "");
    const isHmrConnection = urlString.includes("webpack-hmr") || urlString.includes("_next/webpack-hmr");

    let ws;
    try {
      ws = new originalWebSocket(url, protocols);
    } catch (error) {
      // If it's an HMR connection, silently fail
      if (isHmrConnection) {
        // Return a mock WebSocket that does nothing
        return {
          readyState: 3, // CLOSED
          url: urlString,
          protocol: "",
          extensions: "",
          binaryType: "blob",
          bufferedAmount: 0,
          onopen: null,
          onerror: null,
          onclose: null,
          onmessage: null,
          close: function() {},
          send: function() {},
          addEventListener: function() {},
          removeEventListener: function() {},
          dispatchEvent: function() { return true; },
          CONNECTING: 0,
          OPEN: 1,
          CLOSING: 2,
          CLOSED: 3
        };
      }
      throw error;
    }

    // For HMR connections, suppress all error handling
    if (isHmrConnection) {
      // Override addEventListener to suppress error/close events
      const originalAddEventListener = ws.addEventListener.bind(ws);
      ws.addEventListener = function (type, listener, options) {
        if (type === "error" || type === "close") {
          // Don't add listeners for error/close on HMR connections
          return;
        }
        return originalAddEventListener(type, listener, options);
      };

      // Suppress onerror and onclose handlers
      Object.defineProperty(ws, 'onerror', {
        get: function() { return null; },
        set: function() { /* ignore */ },
        configurable: true
      });

      Object.defineProperty(ws, 'onclose', {
        get: function() { return null; },
        set: function() { /* ignore */ },
        configurable: true
      });

      // Wrap close to prevent errors
      const originalClose = ws.close.bind(ws);
      ws.close = function() {
        try {
          originalClose();
        } catch (e) {
          // Ignore close errors
        }
      };
    }

    return ws;
  };
})();

'use client';

import { useState } from 'react';
import { DashboardCard } from './DashboardCard';
import { DashboardCardSection } from './DashboardCardSection';
import { MsqdxTypography, MsqdxFormField, MsqdxButton } from '@msqdx/react';
import { Box } from '@mui/material';

export type BioCardEditProps = {
  bio: string;
  expanded: boolean;
  onToggle: (id: string) => void;
  onSave?: (bio: string) => Promise<void>;
};

export function BioCardEdit({ bio, expanded, onToggle, onSave }: BioCardEditProps) {
  const [localBio, setLocalBio] = useState(bio);
  const [saving, setSaving] = useState(false);

  const handleSave = async () => {
    if (onSave) {
      setSaving(true);
      try {
        await onSave(localBio);
      } finally {
        setSaving(false);
      }
    }
  };

  return (
    <DashboardCard
      id="bio"
      title="Bio"
      icon="description"
      iconColor={{ color: '#a0a' }}
      expanded={expanded}
      onToggle={onToggle}
    >
      <DashboardCardSection title="Biography">
        <MsqdxFormField
          label="Bio"
          value={localBio}
          onChange={(e) => setLocalBio((e.target as HTMLTextAreaElement).value)}
          multiline
          minRows={3}
        />
        {onSave && (
          <MsqdxButton size="small" brandColor="green" onClick={handleSave} disabled={saving} sx={{ mt: 1 }}>
            Save
          </MsqdxButton>
        )}
      </DashboardCardSection>
    </DashboardCard>
  );
}

